void sense_notify_skd_not_detect(void)
{
  if(rke.bit.smart_key)
    { 
      rke.bit.smart_key = FALSE ;

      cmd_q_insert   (INPUT_SKD_CLR, COMMAND_INSERT_TIMEOUT);

      #if DBG_SENSE == 1
       
        sense_notify_dbg_print("\nSense Skd Not Detect" , NULL , NULL);
      
      #endif
    }
}

//--------------------------------------------------------------------------------

void sense_notify_skd_detect(void)
{
  if(!rke.bit.smart_key)
    { 
      rke.bit.smart_key = TRUE;

      cmd_q_insert   (INPUT_SKD_SET, COMMAND_INSERT_TIMEOUT);

      #if DBG_SENSE == 1
       
        sense_notify_dbg_print("\nSense Skd Detect" , NULL , NULL);
      
      #endif
    }
}

